121	  // -----------------------------------------------------------------------
122	  // Static factory
123	  // -----------------------------------------------------------------------
124	
125	  /**
126	   * Create a mock LLMClient that does **not** make real API calls.
127	   *
128	   * @param stubResponse  Return this LLMResponse on success, or throw this
129	   *                      Error on failure.  The full retry machinery is still
130	   *                      active so you can test retry exhaustion.
131	   */
132	  static createMock(stubResponse: LLMResponse | Error): LLMClient {
133	    const mockAnthropic = {
134	      messages: {
135	        create: async (): Promise<Message> => {
136	          if (stubResponse instanceof Error) {
137	            throw stubResponse;
138	          }
139	          return {
140	            id: 'mock_msg_id',
141	            type: 'message',
142	            role: 'assistant',
143	            content: [{ type: 'text', text: stubResponse.content }],
144	            model: stubResponse.model,
145	            usage: {
146	              input_tokens: stubResponse.usage.inputTokens,
147	              output_tokens: stubResponse.usage.outputTokens,
148	            },
149	          } as Message;
150	        },
151	      },
152	    };
153	
154	    return new LLMClient({ anthropic: mockAnthropic as unknown as Anthropic });
155	  }
156	
157	  // -----------------------------------------------------------------------
158	  // Private helpers
159	  // -----------------------------------------------------------------------
160	
161	  /**
162	   * Determine whether an error is worth retrying.
163	   *
164	   * Retry-able:
165	   *   - Network / connection errors  (status === undefined)
166	   *   - HTTP 429 (rate-limit)
167	   *   - HTTP 5xx (server errors)
168	   *
169	   * Non-retry-able (thrown immediately):
170	   *   - HTTP 401 (auth)
171	   *   - HTTP 403 (permission)
172	   *   - HTTP 400 (bad request)
173	   */
174	  private isRetryable(err: unknown): boolean {
175	    const error = err as { status?: number };
176	    const status = error.status;
177	
178	    // Non-retry-able status codes
179	    if (status === 401 || status === 403 || status === 400) {
180	      return false;
181	    }
182	
183	    // Retry-able: rate limits, server errors, network timeouts
184	    if (status === 429) return true;
185	    if (status !== undefined && status >= 500) return true;
186	    if (status === undefined) return true; // e.g. APIConnectionTimeoutError
187	
188	    return false;
189	  }
190	
191	  /** Promise-based delay for retry back-off. */
192	  private sleep(ms: number): Promise<void> {
193	    return new Promise((resolve) => setTimeout(resolve, ms));
194	  }
195	}
